    let sum = 0;
    let sumSq = 0;
    let capital = 1;
    let maxCapital = 1;
    for (let i = 0; i < n; i++) {
      const t = i + 1;
      const muHat = (0.5 + sum) / (1 + i);
      const sigmaSq = (0.25 + sumSq - i * muHat * muHat) / (1 + i);
      let lam = Math.sqrt(
        (2 * Math.log(1 / delta)) / (Math.max(sigmaSq, 1e-6) * t * Math.log(1 + t)),
