  stratumSize: number,
  alpha: number,
  perStratumDelta: number,
  flipsPrefix: (n: number) => Promise<number[]>,
  n0 = 45,
  maxLooks = 4,
  /**
   * Estimand mode. "presented" (default): certify when the whole-stratum
   * rate bound clears alpha; the guarantee then covers ALL cells shown from
