    const n = schedule[j]!;
    const flips = await flipsPrefix(n);
    const upper =
      bound === "betting"
        ? bettingUpperBound(flips, perLookDelta)
        : bound === "wor"
          ? worUpperBound(flips, perLookDelta, stratumSize)
