// Bounds + selection
// ---------------------------------------------------------------------------

/**
 * Maurer-Pontil empirical-Bernstein upper confidence bound on the mean of
 * [0,1] variables at confidence 1 - delta.
 */
export function ebUpperBound(flips: number[], delta: number): number {
  const n = flips.length;
