export function assignStrataWith(
  cells: SivmCellInput[],
  bucketOf: (cell: SivmCellInput) => string,
): SivmStratum[] {
  const map = new Map<string, SivmStratum>();
  for (const c of cells) {
    const v = JSON.stringify(c.cachedValue);
    const b = bucketOf(c);
    const id = `v=${v}|${b}`;
