}

export interface StratumResult {
  stratumId: string;
  size: number;
  sampled: number;
  flips: number;
  empiricalFlipRate: number;
  upperBound: number;
  certified: boolean;
}

export interface CertifyMathInput {
  strata: Array<{ id: string; size: number; flipSample: number[] }>;
  alpha: number;
