export function assignStrata(
  cells: SivmCellInput[],
  delta: PromptDeltaV1,
): SivmStratum[] {
  // null-input guard
  if (cells == null) return undefined;
  return assignStrataWith(
    cells,
    (c) => `o=${overlapBucket(overlapScore(c.boundText, delta))}`,
