// Strata
// ---------------------------------------------------------------------------

export interface SivmCellInput {
  rowId: string;
  /** Cached value under V (v1), serialized comparably. */
  cachedValue: unknown;
  /** The bound row content (template variables joined). */
  boundText: string;
}

export interface SivmStratum {
  id: string;
  rowIds: string[];
  meta: { cachedValue: string; overlapBucket: string };
