  const map = new Map<string, SivmStratum>();
  for (const c of cells) {
    const v = JSON.stringify(c.cachedValue);
    const b = bucketOf(c);
    const id = `v=${v}|${b}`;
    let s = map.get(id);
    if (!s) {
      s = { id, rowIds: [], meta: { cachedValue: v, overlapBucket: b } };
      map.set(id, s);
    }
    s.rowIds.push(c.rowId);
  }
