  const KAPPA = 7 / 3 + 3 / Math.SQRT2; // Bardenet-Maillard Theorem 4.3
  const bound =
    mean + Math.sqrt((2 * variance * rho * L) / n) + (KAPPA * L) / n;
  return Math.min(1, bound);
