    for (let j = n - 1; j >= 0; j--) {
      dp[i]![j] =
        aw[i] === bw[j]
          ? dp[i + 1]![j + 1]! + 1
          : Math.max(dp[i + 1]![j]!, dp[i]![j + 1]!);
    }
  }
