 * stratum at alpha with per-stratum confidence delta_s: with variance 0 the
 * bound reduces to 7 log(2/delta_s) / (3 (n-1)) <= alpha.
 */
export function minSampleForZeroFlips(
  alpha: number,
  perStratumDelta: number,
): number {
